           "Yaya", "A88888888", "jiang@gmail.com", "2003/06/18"]
for t in targets:
    rects = page.search_for(t)
    for r in rects:
        print(f"{t!r}: x0={r.x0:.1f} y0={r.y0:.1f} x1={r.x1:.1f} y1={r.y1:.1f}")

print("\n--- text spans with positions ---")
d = page.get_text("dict")
for b in d["blocks"]:
    if b["type"] != 0:
        continue
    for l in b["lines"]:
        for s in l["spans"]:
            print(f"span: {s['text']!r} bbox=({s['bbox'][0]:.1f},{s['bbox'][1]:.1f},{s['bbox'][2]:.1f},{s['bbox'][3]:.1f}) font={s['font']} size={s['size']:.1f}")

print("\n--- drawings (lines/rects) ---")
for d in page.get_drawings():
    for item in d["items"]:
        if item[0] == "l":
            p1, p2 = item[1], item[2]
            print(f"line: ({p1.x:.1f},{p1.y:.1f}) -> ({p2.x:.1f},{p2.y:.1f})")
        elif item[0] == "re":
            print(f"rect: {item[1]}")

